var dgeequ = require( './../lib/ndarray.js' );


// FIXTURES //

var ROW_MAJOR_3X3 = require( './fixtures/row_major_3x3.json' );
var COLUMN_MAJOR_3X3 = require( './fixtures/column_major_3x3.json' );
