tape( 'the function supports an index offset and stride for the output array', function test( t ) {
	var expected;
	var data;
	var info;
	var out;
	var A;
	var R;
	var C;

	data = ROW_MAJOR_3X3;

	A = new Float64Array( data.A );
	R = new Float64Array( data.R );
	C = new Float64Array( data.C );

	// Interleave the output array with sentinel values which should be left unmodified...
	out = new Float64Array( [ -1.0, -1.0, 0.0, -1.0, 0.0, -1.0, 0.0 ] );

	info = dgeequ( data.M, data.N, A, data.strideA1, data.strideA2, data.offsetA, R, data.strideR, data.offsetR, C, data.strideC, data.offsetC, out, 2, 2 );

	expected = new Float64Array( [ -1.0, -1.0, data.out_expected[ 0 ], -1.0, data.out_expected[ 1 ], -1.0, data.out_expected[ 2 ] ] );

	t.strictEqual( info, data.info, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function supports a negative stride for the output array', function test( t ) {
	var expected;
	var data;
	var info;
	var out;
	var A;
	var R;
	var C;

	data = ROW_MAJOR_3X3;

	A = new Float64Array( data.A );
	R = new Float64Array( data.R );
	C = new Float64Array( data.C );
	out = new Float64Array( 3 );

	info = dgeequ( data.M, data.N, A, data.strideA1, data.strideA2, data.offsetA, R, data.strideR, data.offsetR, C, data.strideC, data.offsetC, out, -1, 2 );

	expected = new Float64Array( [ data.out_expected[ 2 ], data.out_expected[ 1 ], data.out_expected[ 0 ] ] );

	t.strictEqual( info, data.info, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns early if M = 0 or N = 0', function test( t ) {
	var expected;
	var info;
	var out;
	var A;
	var R;
	var C;

	A = new Float64Array( 0 );
	R = new Float64Array( 0 );
	C = new Float64Array( 0 );
	expected = new Float64Array( [ 1.0, 1.0, 0.0 ] );

	out = new Float64Array( 3 );
	info = dgeequ( 0, 0, A, 1, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 );
	t.strictEqual( info, 0, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	out = new Float64Array( 3 );
	info = dgeequ( 0, 3, A, 1, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 );
	t.strictEqual( info, 0, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	out = new Float64Array( 3 );
	info = dgeequ( 3, 0, A, 1, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 );
	t.strictEqual( info, 0, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	t.end();
});
